package com.ryanjei.orushio.pve.security;
import static org.junit.jupiter.api.Assertions.*;import java.time.*;import org.junit.jupiter.api.Test;
class AuthServiceTest { @Test void 失敗上限と期限切れ削除を扱う(){MutableClock clock=new MutableClock();AuthService auth=new AuthService(clock);for(int i=0;i<5;i++)assertEquals(AuthService.ResultType.INVALID,auth.exchangeLimited("bad","client").type());assertEquals(AuthService.ResultType.RATE_LIMITED,auth.exchangeLimited("bad","client").type());clock.advance(Duration.ofMinutes(2));assertEquals(AuthService.ResultType.INVALID,auth.exchangeLimited("bad","client").type());assertEquals(1,auth.failureEntryCount());} @Test void 正常tokenは一度だけ交換できる(){AuthService auth=new AuthService();String token=auth.issueBootstrap(Duration.ofMinutes(1));assertEquals(AuthService.ResultType.SUCCESS,auth.exchangeLimited(token,"c").type());assertEquals(AuthService.ResultType.INVALID,auth.exchangeLimited(token,"c").type());}@Test void 期限切れbootstrapを拒否する(){MutableClock clock=new MutableClock();AuthService auth=new AuthService(clock);String token=auth.issueBootstrap(Duration.ofSeconds(1));clock.advance(Duration.ofSeconds(2));assertEquals(AuthService.ResultType.INVALID,auth.exchangeLimited(token,"c").type());} private static final class MutableClock extends Clock{Instant now=Instant.parse("2026-01-01T00:00:00Z");public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return this;}public Instant instant(){return now;}void advance(Duration d){now=now.plus(d);}}
}
